pub type Matrix<T> = Vec<Vec<T>>;

/// Broadcasts a vector `a` into a matrix of the specified `shape`.
/// 
/// # Parameters
/// - `a`: A vector of `i8` values to be broadcasted.
/// - `shape`: A vector of `u8` values representing the desired shape of the output matrix.
/// 
/// # Returns
/// A matrix of `i8` values with the specified shape, where the elements of `a` are replicated
/// according to the shape provided.
///
/// # Requires
/// - `shape` must have exactly 2 elements, representing the number of rows and columns.
/// - The length of `a` must be either equal to the number of rows or the number of columns.
/// 
/// # Ensures
/// - The returned matrix has dimensions `shape[0]` x `shape[1]`.
/// - Each row of the matrix is filled with the corresponding element from `a` based on its shape.
#[verus::spec]
fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Requires that shape has exactly 2 elements
    assert!(shape.len() == 2);
    let r = shape[0] as usize; // Number of rows
    let c = shape[1] as usize; // Number of columns
    let len = a.len(); // Length of the input array

    // Initialize the matrix with the specified shape
    let mut matrix = vec![vec![0; c]; r];

    // Invariant: The matrix is always of size r x c
    // Decreases clause: The loop variable i decreases from r to 0
    if r == len {
        // Treat `a` as a column vector
        for i in 0..r {
            // Invariant: 0 <= i < r
            for j in 0..c {
                // Invariant: 0 <= j < c
                matrix[i][j] = a[i]; // Replicate the i-th element across the row
            }
        }
    } else {
        // Treat `a` as a row vector
        for i in 0..r {
            // Invariant: 0 <= i < r
            for j in 0..c {
                // Invariant: 0 <= j < c
                matrix[i][j] = a[j]; // Replicate the j-th element across the column
            }
        }
    }

    // Ensures that the matrix has the correct dimensions
    assert!(matrix.len() == r);
    assert!(matrix.iter().all(|row| row.len() == c));

    matrix
}

fn main() {
    // Example usage
    let a = vec![1, 2, 3];
    let shape = vec![3, 2];
    let result = broadcast(a, shape);
    
    for row in result {
        println!("{:?}", row);
    }
}